def parse_row(line):
    parts = line.split(",")
    if len(parts) != 2:
        return None
    name, value = parts
    try:
        return {"name": name, "value": int(value)}
    except ValueError:
        return None


def load_rows(text):
    rows = []
    for line in text.splitlines():
        if line:
            row = parse_row(line)
            if row is not None:
                rows.append(row)
    return rows

